insert into public.iskra_shared_kb (topic, topic_norm, body, tags) values
  ('Как решать задачи по математике', public.iskra_kb_norm('Как решать задачи по математике'), 'Прочитай задачу дважды и выпиши, что дано и что нужно найти. Обозначь неизвестное буквой и переведи условие в уравнение или в действия. Решай по шагам, записывая каждое действие, а не в голове. В конце проверь: подставь ответ обратно в условие и посмотри, разумен ли он — отрицательных яблок не бывает. Если не выходит, нарисуй схему: рисунок часто делает решение очевидным.', 'учёба, математика, задачи'),
  ('Проценты: как считать быстро', public.iskra_kb_norm('Проценты: как считать быстро'), 'Процент — это сотая часть. Чтобы найти 1%, раздели число на 100; чтобы найти 20%, умножь на 0,2. Скидка 30% на 2000 рублей — это 2000 × 0,3 = 600, платить 1400. Скидка и наценка не отменяют друг друга: минус 20%, потом плюс 20% дают не исходное число, а меньше. Проценты по вкладу за год — это сумма × ставка; сложный процент начисляет проценты на проценты.', 'учёба, математика, проценты'),
  ('Дроби: сложение, умножение, деление', public.iskra_kb_norm('Дроби: сложение, умножение, деление'), 'Складывать можно только дробями с одинаковым знаменателем: 1/3 + 1/4 приводим к 12 и получаем 4/12 + 3/12 = 7/12. Умножение проще всего — числитель на числитель, знаменатель на знаменатель: 2/3 × 3/4 = 6/12 = 1/2. При делении переверни вторую дробь и умножь. Смешанные числа переводи в неправильные: 1½ = 3/2. Сокращай до умножения, а не после.', 'учёба, математика, дроби'),
  ('Теорема Пифагора', public.iskra_kb_norm('Теорема Пифагора'), 'В прямоугольном треугольнике квадрат гипотенузы равен сумме квадратов катетов: a² + b² = c², где c — сторона напротив прямого угла. Катеты 3 и 4 дают гипотенузу 5. Работает только в прямоугольном треугольнике. Пригодится в ремонте, чтобы проверить прямой угол, на карте, чтобы посчитать расстояние, и в физике при сложении перпендикулярных скоростей.', 'учёба, математика, геометрия'),
  ('Уравнения с одним неизвестным', public.iskra_kb_norm('Уравнения с одним неизвестным'), 'Цель — оставить неизвестное одно на одной стороне. Переносишь число через знак равенства — меняешь знак: x + 5 = 12, значит x = 12 − 5. Умножение и деление переносятся обратным действием: 3x = 15, значит x = 15 ÷ 3. Делай одно действие за раз и записывай его. Проверка обязательна: подставь найденный x в исходное уравнение.', 'учёба, математика, уравнения'),
  ('Физика: сила, масса, ускорение', public.iskra_kb_norm('Физика: сила, масса, ускорение'), 'Второй закон Ньютона: F = m × a, сила равна массе, умноженной на ускорение. Один ньютон — сила, которая разгоняет килограмм на метр в секунду за секунду. Отсюда бытовой смысл: тяжёлое тело труднее разогнать и труднее остановить, поэтому гружёная машина тормозит дольше. Масса и вес — не одно и то же: масса не меняется, а вес на Луне в шесть раз меньше.', 'учёба, физика, ньютон'),
  ('Электричество: ток, напряжение, сопротивление', public.iskra_kb_norm('Электричество: ток, напряжение, сопротивление'), 'Закон Ома: I = U / R. Напряжение в вольтах — это давление, сила тока в амперах — сколько течёт, сопротивление в омах — насколько узкая труба. Мощность P = U × I: чайник на 220 вольт и 9 ампер даёт около 2000 ватт. Отсюда правило: чем больше приборов в одной розетке, тем больше ток и нагрев провода. Поэтому тройники и удлинители греются.', 'учёба, физика, электричество'),
  ('Химия: как читать уравнение реакции', public.iskra_kb_norm('Химия: как читать уравнение реакции'), 'Слева исходные вещества, справа продукты, между ними стрелка. Число атомов каждого элемента слева и справа должно совпадать — его выравнивают коэффициентами перед формулами. Например 2H₂ + O₂ → 2H₂O. Индексы внутри формулы менять нельзя: H₂O и H₂O₂ — разные вещества. Коэффициенты всегда целые числа.', 'учёба, химия, реакции'),
  ('Таблица Менделеева: как ею пользоваться', public.iskra_kb_norm('Таблица Менделеева: как ею пользоваться'), 'Порядковый номер равен числу протонов и числу электронов в нейтральном атоме. Номер группы, то есть столбца, показывает, сколько электронов на внешней оболочке — отсюда свойства элемента. Горизонтальные ряды называются периодами. Металлы стоят слева и снизу, неметаллы справа сверху, инертные газы — крайний правый столбец. Атомная масса записана под символом.', 'учёба, химия, таблица менделеева'),
  ('Строение клетки', public.iskra_kb_norm('Строение клетки'), 'Основные части: мембрана — граница, цитоплазма — внутренняя среда, ядро — ДНК и управление, митохондрии — энергия, рибосомы — синтез белка. У растений дополнительно есть клеточная стенка и хлоропласты, поэтому растения зелёные и жёсткие. У животной клетки стенки нет. Митохондрии называют энергостанциями: там из глюкозы получается энергия.', 'учёба, биология, клетка'),
  ('Как писать сочинение', public.iskra_kb_norm('Как писать сочинение'), 'Сначала план: тема, главная мысль, три аргумента, вывод. Вступление на два-три предложения — сразу заяви мысль. В основной части один абзац равен одному аргументу, и к нему нужен пример из текста или из жизни. Заключение — это ответ на вопрос темы, а не пересказ. Пиши черновик не думая о красоте, потом убери воду и повторы.', 'учёба, сочинение, русский язык'),
  ('Как пересказывать текст', public.iskra_kb_norm('Как пересказывать текст'), 'Прочитай и выпиши пять-семь ключевых слов. По ним перескажи вслух своими словами, не подглядывая в текст. Держи структуру: что случилось в начале, что изменилось, чем закончилось. Не заучивай предложения: пересказ держит смысл, а не слова. Если застрял, вернись к своим ключевым словам — они вытянут дальше.', 'учёба, пересказ, память'),
  ('Времена в английском: простое объяснение', public.iskra_kb_norm('Времена в английском: простое объяснение'), 'Три времени и три вида: прошлое, настоящее, будущее, каждое простое, длительное и совершённое. Простое — факт и привычка: I work. Длительное — процесс сейчас: I am working. Совершённое — результат к моменту: I have worked. Начинай с простых времён, они закрывают большую часть речи. Вспомогательный глагол показывает время, смысловой — действие.', 'английский, времена, грамматика'),
  ('Present Perfect и Past Simple', public.iskra_kb_norm('Present Perfect и Past Simple'), 'Past Simple — законченное действие в известное время: I saw him yesterday. Present Perfect — результат важен сейчас, а время не названо: I have seen this film, поэтому знаю его. Слова-подсказки: yesterday, ago, last week тянут к простому прошедшему; already, just, ever, never, yet — к совершённому. Если можешь назвать когда, обычно хватает Past Simple.', 'английский, present perfect, past simple'),
  ('Артикли a и the', public.iskra_kb_norm('Артикли a и the'), 'a или an — один из многих, впервые упомянули: a dog. the — конкретный, уже известный или единственный: the dog, the sun. Артикль не ставится перед именами, городами, большинством стран, языками и во множественном числе в общем смысле: dogs are loyal. Если существительное неисчисляемое и речь о веществе вообще, артикль тоже не нужен: I like tea.', 'английский, артикли, грамматика'),
  ('Неправильные глаголы: как учить', public.iskra_kb_norm('Неправильные глаголы: как учить'), 'Их около двухсот, но активно нужны шестьдесят-семьдесят. Учи тройками: go — went — gone, take — took — taken. Списком зубрить скучно, поэтому бери по десять штук и придумывай с каждым по одному предложению о своей жизни. Проверяй себя через день, через три дня и через неделю. Те, где все три формы одинаковые, запоминаются сами.', 'английский, глаголы, слова'),
  ('Как запоминать английские слова', public.iskra_kb_norm('Как запоминать английские слова'), 'Учи не отдельные слова, а фразы: не decision, а make a decision. Карточки с вопросом и ответом, повтор через день, три дня и неделю. Проговаривай вслух и составляй предложение про себя — так слово попадает в речь, а не только в пассивный запас. Десять слов в день с повторением лучше, чем сто за один вечер и ноль через неделю.', 'английский, слова, память'),
  ('Фразовые глаголы', public.iskra_kb_norm('Фразовые глаголы'), 'Глагол с предлогом меняет смысл: look — смотреть, look for — искать, look after — заботиться, look forward to — ждать с нетерпением. Учить их надо целой фразой с примером, а не переводом. Некоторые разделяются: turn the light off или turn off the light, но с местоимением только turn it off. В разговорной речи они встречаются чаще, чем книжные синонимы.', 'английский, фразовые глаголы'),
  ('Что такое файл и папка', public.iskra_kb_norm('Что такое файл и папка'), 'Файл — это документ, фотография или программа, у него есть имя и расширение после точки: docx, jpg, mp3. Расширение говорит, чем файл открывать. Папка — контейнер для файлов, внутри могут быть другие папки. Путь — это адрес файла: Диск D, папка Фото, папка 2026, файл отпуск.jpg. Копирование оставляет файл на месте, перемещение убирает с прежнего места.', 'компьютер, файлы, новичок'),
  ('Порядок в файлах на компьютере', public.iskra_kb_norm('Порядок в файлах на компьютере'), 'Заведи несколько крупных папок верхнего уровня: Документы, Фото, Работа, Личное. Внутри раскладывай по годам или проектам. Называй файл так, чтобы через год понять без открытия: 2026-05 договор аренды. Не храни всё на рабочем столе, это свалка. Десять минут раз в месяц на разбор загрузок экономят часы поиска потом.', 'компьютер, файлы, порядок'),
  ('Документ: что нужно уметь', public.iskra_kb_norm('Документ: что нужно уметь'), 'Набрать и отформатировать текст: заголовки, жирный, курсив, списки, отступы. Вставить картинку и таблицу, выровнять по краю. Настроить поля и размер шрифта: обычно 12-14 пунктов и поля 2 сантиметра. Сохранить в docx и в pdf, потому что pdf откроется везде одинаково. Перед отправкой проверь орфографию, нумерацию страниц и имя файла.', 'компьютер, документы, word'),
  ('Excel: формулы с нуля', public.iskra_kb_norm('Excel: формулы с нуля'), 'Ячейка имеет адрес из буквы столбца и номера строки: A1. Формула начинается со знака равно: =A1+B1, =A1*0,2, =СУММ(A1:A10). Знак доллара делает ссылку абсолютной, она не сдвигается при копировании: $A$1. Диапазон A1:A10 — это десять ячеек столбца. Сначала посчитай пару примеров вручную, чтобы убедиться, что формула верна.', 'компьютер, excel, таблицы'),
  ('Что такое браузер', public.iskra_kb_norm('Что такое браузер'), 'Браузер — программа для сайтов: Chrome, Firefox, Edge, Safari. Вкладки — несколько страниц в одном окне, закладки — сохранённые адреса. Адрес сайта вводят в строку сверху, поиск тоже идёт из неё. Режим инкогнито не прячет тебя от сайта, он только не сохраняет историю на этом устройстве. Очистка кэша помогает, когда сайт выглядит странно или не обновляется.', 'компьютер, интернет, браузер'),
  ('Как сохранить и напечатать документ', public.iskra_kb_norm('Как сохранить и напечатать документ'), 'Ctrl+S сохраняет, Ctrl+P печатает, Ctrl+Z отменяет последнее действие. Перед печатью открой предпросмотр: часто текст уезжает на вторую страницу из-за полей. Чтобы получить pdf, выбери печать и вместо принтера «Сохранить как PDF». В телефоне печать идёт через меню «Поделиться». Беспроводной принтер должен быть в той же сети, что и компьютер.', 'компьютер, печать, документы'),
  ('Как сделать скриншот', public.iskra_kb_norm('Как сделать скриншот'), 'Windows: Win+Shift+S выделяет область, PrtSc копирует весь экран в буфер. Mac: Cmd+Shift+4. Android: кнопка питания и громкость вниз одновременно. iPhone: боковая кнопка и громкость вверх. Снимок сохраняется в «Изображения» или папку «Снимки экрана». Если нужно отправить, вставь из буфера в чат или найди файл в папке.', 'компьютер, скриншот, телефон'),
  ('Компьютер не включается', public.iskra_kb_norm('Компьютер не включается'), 'Проверяй по порядку: розетка и кабель, выключатель на блоке питания сзади, лампочка на блоке. Если гудит, но картинки нет, проверь кабель монитора и переключи вход. Ноутбук: отсоедини зарядку, зажми кнопку питания на пятнадцать секунд, включи снова. Не помогло — не разбирай сам, если действует гарантия: разборка её отменяет.', 'компьютер, поломка, ремонт'),
  ('Бюджет на месяц', public.iskra_kb_norm('Бюджет на месяц'), 'Запиши все доходы и обязательные расходы: жильё, связь, транспорт, еда, кредиты. Остаток раздели на три части: накопления хотя бы десять процентов, желания и запас на неожиданное. Веди учёт две недели — обычно находится одна-две утечки, о которых не думал. Планируй еду и покупки списком: импульсивные мелочи съедают больше, чем крупные траты.', 'деньги, бюджет, планирование'),
  ('Как выйти из долгов', public.iskra_kb_norm('Как выйти из долгов'), 'Выпиши все долги: сумма, ставка, минимальный платёж. Закрывай сначала самый дорогой по процентам, по остальным плати минимум. Кредитку гаси в льготный период, иначе проценты огромные. Не бери новый кредит, чтобы закрыть старый: долг только вырастет. Если платить нечем, позвони в банк и попроси реструктуризацию — это лучше просрочки.', 'деньги, долги, кредит'),
  ('Кредит: что важно знать', public.iskra_kb_norm('Кредит: что важно знать'), 'Смотри полную стоимость кредита, а не рекламную ставку: в неё входят страховки и комиссии. Платёж не должен превышать тридцать-сорок процентов дохода. Досрочное погашение выгоднее в начале срока. Про страховку спрашивай отдельно: часто её можно не брать, но ставка вырастет. Просрочка портит кредитную историю на годы, поэтому лучше договориться заранее.', 'деньги, кредит, банк'),
  ('Ипотека: как считается платёж', public.iskra_kb_norm('Ипотека: как считается платёж'), 'Платёж состоит из тела долга и процентов, и в начале почти всё уходит на проценты. Ориентир: при ставке восемнадцать процентов на двадцать лет каждый миллион долга стоит около пятнадцати тысяч рублей в месяц. Считай не только платёж, но и налог, страховку, ремонт, коммунальные. Первоначальный взнос от двадцати процентов снижает ставку. Чем короче срок, тем меньше переплата.', 'деньги, ипотека, жильё'),
  ('Страховка: зачем она нужна', public.iskra_kb_norm('Страховка: зачем она нужна'), 'Обязательные — ОСАГО для машины и ОМС для человека, последнее бесплатно. Добровольные — каско, ДМС, страхование квартиры и жизни. Смысл страховки в защите от редкого, но дорогого события, а не в заработке. Сравнивай франшизу, то есть часть убытка за свой счёт, и список исключений в правилах. Дешёвый полис с множеством исключений бесполезен.', 'деньги, страховка'),
  ('Как не попасть в финансовую пирамиду', public.iskra_kb_norm('Как не попасть в финансовую пирамиду'), 'Признаки: обещают доход в разы выше банковского без риска, платят за приглашённых друзей, торопят «успей войти», нет лицензии, деньги просят на карту частного лица. Если выплаты идут из взносов новых участников, это пирамида, и она рушится всегда. Проверить организацию можно в справочнике лицензий Банка России. Отзывы «у меня получилось» часто пишут сами организаторы.', 'деньги, мошенники, пирамида'),
  ('Наличные или карта', public.iskra_kb_norm('Наличные или карта'), 'Карта удобнее и безопаснее: при краже её можно заблокировать и оспорить платёж, а наличные пропадают навсегда. Но часть трат полезно держать наличными: расставаться с бумажками психологически труднее, чем с цифрами, и расходы видны. Небольшая сумма наличных пригодится при сбое связи. Не держи все деньги на одной карте, привязанной к интернету.', 'деньги, карта, наличные'),
  ('Как копить на цель', public.iskra_kb_norm('Как копить на цель'), 'Раздели сумму на срок: нужно сто двадцать тысяч за год, значит по десять тысяч в месяц. Заведи отдельный счёт и настрой автоперевод в день зарплаты: копить надо до трат, а не из остатка. Начни с малой суммы, даже с тысячи рублей, важна привычка. Не держи накопления на карте повседневных трат, иначе они растворятся.', 'деньги, накопления, цель'),
  ('Простуда: что делать', public.iskra_kb_norm('Простуда: что делать'), 'ОРВИ лечат по симптомам: покой, обильное питьё, жаропонижающее при необходимости, промывание носа. Витамин C и противовирусные без доказанной пользы большинству не нужны. Антибиотики на вирус не действуют. Обычно болезнь идёт пять-семь дней, кашель может держаться до трёх недель. К врачу — если температура выше 39 держится больше трёх дней, тяжело дышать или болит в груди.', 'здоровье, простуда, орви'),
  ('Температура: когда сбивать', public.iskra_kb_norm('Температура: когда сбивать'), 'Взрослому не обязательно сбивать до 38,5: температура помогает бороться с инфекцией. Сбивают, если тяжело переносить, есть болезни сердца или судороги в прошлом. Парацетамол или ибупрофен — по инструкции, не чаще указанного. Обильное питьё важнее градусника. У детей порог ниже, там решение лучше принимать вместе с врачом.', 'здоровье, температура, лекарства'),
  ('Антибиотики: правила', public.iskra_kb_norm('Антибиотики: правила'), 'Принимать строго по назначению врача и полным курсом, даже если стало легче: недолеченное даёт устойчивые бактерии. Запивать водой, не молоком и не чаем. Антибиотик бьёт и по полезным бактериям, отсюда понос и молочница, о них стоит сказать врачу. Не оставляй препарат «на следующий раз» и не делись им с другими.', 'здоровье, антибиотики, лекарства'),
  ('Как правильно измерять давление', public.iskra_kb_norm('Как правильно измерять давление'), 'Сиди, спина на спинке, рука на столе на уровне сердца, после пяти минут покоя. Манжета на плечо, а не на одежду. Норма у взрослого примерно 120 на 80, повышенным считается от 140 на 90, но диагноз ставит врач по нескольким измерениям. Кофе и сигареты — не раньше чем за полчаса до замера. Записывай результаты с датой и временем.', 'здоровье, давление, измерение'),
  ('Первая помощь при порезе', public.iskra_kb_norm('Первая помощь при порезе'), 'Промой водой, прижми чистым платком или бинтом на пять-десять минут, чтобы остановилась кровь. Обработай края антисептиком, заклей пластырем или перевяжи. Жгут нужен, только если кровь бьёт струёй. В больницу — если рана глубокая или зияет, если порезался стеклом или ржавым металлом, если кровь не останавливается или немеет вокруг раны.', 'здоровье, первая помощь, порез'),
  ('Растяжение: что делать', public.iskra_kb_norm('Растяжение: что делать'), 'В первые часы: покой, холод через ткань по пятнадцать-двадцать минут, давящая повязка, нога выше уровня сердца. Греть нельзя первые двое суток, это усилит отёк. Не растирай и не разрабатывай через боль. Боль и отёк обычно спадают за одну-две недели. К врачу — если не можешь наступить на ногу, сустав необычно двигается или слышен хруст.', 'здоровье, растяжение, травма'),
  ('Тарелка здорового человека', public.iskra_kb_norm('Тарелка здорового человека'), 'Примерно половина тарелки — овощи и фрукты, четверть — белок: рыба, мясо, яйца, творог, бобовые. Ещё четверть — гарнир: крупы, картофель, макароны из твёрдых сортов. Добавь ложку масла и воду. Такая тарелка наедает без подсчёта калорий и без запретов. Не дели еду на плохую и хорошую: важнее пропорция и регулярность.', 'здоровье, питание, еда'),
  ('Ходьба: сколько и зачем', public.iskra_kb_norm('Ходьба: сколько и зачем'), 'Тридцать-сорок минут быстрой ходьбы в день снижают давление, сахар и риск болезней сердца. Это примерно пять-семь тысяч шагов сверх обычного; десять тысяч — ориентир, а не строгая норма. Иди в темпе, при котором можешь говорить, но не петь. Начинай с десяти минут и добавляй по пять. Удобная обувь важнее трекера.', 'здоровье, ходьба, спорт'),
  ('Как правильно мыть окна', public.iskra_kb_norm('Как правильно мыть окна'), 'Мой в пасмурный день: на солнце средство высыхает раньше, чем ты его смоешь, и остаются разводы. Сначала рамы и подоконники, потом стекло. Раствор — вода с каплей средства для посуды, для стёкол лучше специальный спрей. Протри сухой микрофиброй или стяжкой сверху вниз. Пластиковые окна не открывай на створку в мороз: механизм ломается.', 'дом, окна, уборка'),
  ('Как утеплить окна на зиму', public.iskra_kb_norm('Как утеплить окна на зиму'), 'Сначала найди, откуда дует: проведи рукой или пламенем свечи у рамы, створки и подоконника. Старые деревянные окна заклеивают или ставят уплотнитель по периметру створки. В пластиковых регулируют створки или меняют уплотнитель, он живёт пять-семь лет. Поролон и «тёплый» скотч — решение на один сезон, а не на годы.', 'дом, окна, зима, утепление'),
  ('Что делать, если прорвало трубу', public.iskra_kb_norm('Что делать, если прорвало трубу'), 'Перекрой воду: кран на стояке, под раковиной или на вводе в квартиру. Открой все краны, чтобы спустить остаток. Позвони в управляющую компанию или аварийную службу. В мокрых местах выключи электричество. Подставь тазы, убери мебель и технику. Сфотографируй ущерб: это понадобится для страховки и разговора с соседями.', 'дом, авария, труба, вода'),
  ('Как выбрать стиральную машину', public.iskra_kb_norm('Как выбрать стиральную машину'), 'Для квартиры хватит загрузки шесть-семь килограммов и глубины до сорока пяти сантиметров, если мало места. Смотри режим быстрой стирки на пятнадцать минут и отжим от тысячи оборотов. Ставь на ровный пол и обязательно выкрути транспортировочные болты сзади, иначе машина «уедет» и сломается. Раз в месяц включай стирку при шестидесяти-девяноста градусах, чтобы не появился запах.', 'дом, техника, стиральная машина'),
  ('Как выбрать холодильник', public.iskra_kb_norm('Как выбрать холодильник'), 'Объём считай по семье: двести пятьдесят-триста литров на двух-трёх человек, больше для большой семьи. Система ноу-фрост избавляет от разморозки, но продукты сохнут; капельная дешевле и лучше хранит овощи. Проверь класс энергопотребления и уровень шума, до сорока децибел считается тихо. Не ставь рядом с плитой и батареей, оставь пять-десять сантиметров от стены для вентиляции.', 'дом, техника, холодильник'),
  ('Насекомые в доме', public.iskra_kb_norm('Насекомые в доме'), 'Моль: сухая одежда в шкафу, лаванда помогает слабо, работают промораживание и феромонные ловушки. Муравьи: найди дорожку, закрой еду, а лучше поставь гель-приманку, которую они унесут в гнездо. Клопов самодельными средствами не вывести, нужен специалист. Тараканы не живут там, где нет еды и воды, поэтому сухие раковины и крошки важнее химии.', 'дом, насекомые, моль, муравьи'),
  ('Как хранить документы', public.iskra_kb_norm('Как хранить документы'), 'Паспортные данные и свидетельства держи отдельно от бытовых бумаг. Бумажные оригиналы — в папке с файлами: паспорт, свидетельства, СНИЛС, ИНН, полисы, договоры. Сканы храни в двух местах: на диске или флешке и в облаке с паролем. Не держи фото паспорта в галерее телефона. Раз в год проверяй сроки полисов, техосмотра и поверки счётчиков.', 'дом, документы, порядок'),
  ('Переезд: план', public.iskra_kb_norm('Переезд: план'), 'За месяц составь список вещей и избавься от лишнего: продай, отдай, выброси. За две недели закажи транспорт и договорись о грузчиках. Подпиши каждую коробку: комната и краткое содержимое. Вещи первой необходимости — постель, зарядки, аптечка, документы, чайник — собери отдельно. В день переезда сфотографируй мебель и проверь, что свет, вода и интернет работают.', 'дом, переезд, планирование'),
  ('Как выбрать первую машину', public.iskra_kb_norm('Как выбрать первую машину'), 'Для первой лучше подержанная популярная модель: дешевле в ремонте и проще продать. Смотри пробег относительно возраста, примерно десять-пятнадцать тысяч километров в год, историю аварий по VIN и число владельцев. Механика проще и дешевле, автомат удобнее в городе. Держи в запасе на ремонт десять-пятнадцать процентов цены. Обязательно возьми с собой того, кто разбирается.', 'авто, покупка, первая машина'),
  ('Что проверить в подержанной машине', public.iskra_kb_norm('Что проверить в подержанной машине'), 'Пробей VIN по открытым базам: залоги, ДТП, пробег, ограничения. Посмотри зазоры кузова и цвет под разным светом — признак перекраски. Проверь пятна масла под капотом и на асфальте. Покатайся: посторонние звуки, рывки, вибрация на скорости. Перед сделкой загони машину на диагностику в независимый сервис: две-три тысячи рублей экономят сотни тысяч.', 'авто, б/у, проверка'),
  ('Как поменять колесо', public.iskra_kb_norm('Как поменять колесо'), 'Остановись на ровном твёрдом месте, включи аварийку и выставь знак позади машины. Ослабь болты до подъёма, иначе колесо будет крутиться. Поднимай домкратом строго под штатное место у порога. Поставь запаску и затяни болты по диагонали. Проверь давление и поезжай в шиномонтаж: запаска обычно «докатка», ехать на ней быстро нельзя.', 'авто, колесо, домкрат'),
  ('Машина не заводится', public.iskra_kb_norm('Машина не заводится'), 'Щёлкает и не крутит — почти всегда аккумулятор: прикури от другого автомобиля или заряди. Крутит, но не схватывает — проверь топливо и подачу, послушай насос. В мороз помогают прогрев и второй аккумулятор. Не крути стартер дольше десяти секунд подряд, он перегреется. Если поломка не твоя, вызови помощь, а не пытайся катить машину сам.', 'авто, поломка, аккумулятор'),
  ('Зимняя езда', public.iskra_kb_norm('Зимняя езда'), 'Тормозной путь на льду втрое-впятеро длиннее. Держи дистанцию вдвое больше, тормози короткими нажатиями без блокировки колёс, руль не крути резко. На скользком трогайся со второй передачи. Зимние шины нужны при устойчивой температуре ниже плюс семи. В гололёд не обгоняй без нужды. В машине держи щётку, трос, лопату и тёплые вещи.', 'авто, зима, гололёд'),
  ('Как написать резюме', public.iskra_kb_norm('Как написать резюме'), 'Одна страница: имя, контакты, коротко о себе на две-три строки, опыт с результатами, навыки, образование. В опыте пиши не обязанности, а итоги: сократил время отчёта с трёх часов до сорока минут. Под каждую вакансию подправь первые строки под её требования. Не пиши стрессоустойчивость и коммуникабельность без примеров. Отправляй в pdf, имя файла — фамилия и должность.', 'работа, резюме, поиск работы'),
  ('Как вести себя на собеседовании', public.iskra_kb_norm('Как вести себя на собеседовании'), 'Подготовь три истории по схеме ситуация, что сделал, результат: успех, ошибка, конфликт. Заранее сформулируй, почему уходишь, без обвинений. Вопросы задают и тебе, поэтому спроси про задачи на первые месяцы и как оценивают работу. Про зарплату уточняй прямо, не откладывай. Опоздание и скрытые сомнения портят впечатление сильнее, чем честное «не знаю, но разберусь».', 'работа, собеседование, резюме'),
  ('Как просить прибавку', public.iskra_kb_norm('Как просить прибавку'), 'Иди с фактами: что сделал за год и как это измерить — сроки, деньги, объёмы. Говори о задаче компании, а не о своих расходах. Назови конкретную сумму или процент и обоснуй рынком: посмотри зарплаты на похожих должностях. Проси встречу заранее, а не в коридоре. Готовься к отказу: спроси, что должно измениться и когда можно вернуться к разговору.', 'работа, зарплата, разговор'),
  ('Как спорить без ссоры', public.iskra_kb_norm('Как спорить без ссоры'), 'Сначала перескажи мысль собеседника своими словами и спроси, верно ли понял: это снимает половину накала. Критикуй действие, а не человека: не «ты вечно опаздываешь», а «когда встреча началась без тебя, вопрос не решился». Говори о своих чувствах через «я». Если накрыло, возьми паузу и вернись к разговору, когда остынешь.', 'психология, отношения, конфликт'),
  ('Активное слушание', public.iskra_kb_norm('Активное слушание'), 'Не перебивай и не готовь ответ, пока человек говорит. Кивай и задавай уточняющие вопросы: что было дальше, а что ты почувствовал. Перескажи главное: значит, начальник поменял сроки и ты не успеваешь. Не давай совет, пока не попросили. Людям чаще нужно, чтобы их услышали, чем чтобы решили проблему. Это работает и дома, и на работе.', 'психология, общение, слушание')
