-- Пятая порция тем для общей базы Искры (60 тем, части 1-3).
-- Запускать по частям: каждый блок самодостаточен и безопасен при повторе.
-- Ожидаемый результат в конце: одно число — сколько всего тем в базе.


on conflict (topic_norm) do update
  set body = excluded.body,
      tags = excluded.tags,
      active = true,
      updated_at = now();

select count(*) as тем_в_общей_базе from public.iskra_shared_kb where active;
